SELECT * FROM studentms.quiz


        quiz_id = #{quiz.quizId}


        AND ctid = #{quiz.ctid}



            AND quiz_title = #{quiz.quizTitle}


            AND quiz_title LIKE CONCAT('%', #{quiz.quizTitle}, '%')




            AND quiz_description = #{quiz.quizDescription}


            AND quiz_description LIKE CONCAT('%', #{quiz.quizDescription}, '%')



ORDER BY create_time DESC;
